  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "明确并行的动机、逻辑轴到 rank 再到设备的映射、输入输出及执行状态。TP 矩阵轴、PP 独立微批、EP 逐专家贡献和 CP 合法 key 集合均有数学定义；区分层输出、logits 与确认 token，没有把未来 token 或其缓存当作已经存在的输入。",
      "evidence": [
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "输入包含固定模型参数、请求 token、位置和 mask、已有状态及并行计划；输出是下一层 hidden、logits 或确认的生成 token。"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "执行状态还包括权重分片、KV/MLA latent、微批激活、路由描述符、softmax 统计、通信区、工作区和未完成访问。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "完整互斥覆盖、贡献恰好一次、集合操作匹配、全局位置/head 映射、消费者可见性及最后使用关系均被列为合法条件；ring、分片形态和重叠被列为设计选择。NCCL 的 count/datatype、root 和 rank 排序约束与所供原文一致；Mixtral gating 及 DeepSeek-V3 选择分数与原 affinity 的区别符合所供材料。",
      "evidence": [
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "分片 G_r 必须满足并集完整且两两不交。"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "集合操作的成员、数量、datatype、归约方式和逻辑顺序必须匹配。本地没有有效 token 不授权某个成员跳过全组已经约定的操作。"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "实数中的等价重排也不保证浮点逐位一致。"
        }
      ]
    },
    "algorithm": {
      "assessment": "sufficient",
      "reason": "四段伪代码给出输入、初始化、推进和结束条件。TP 重建列输出或行部分和；PP 递推连接上下游和阶段内依赖；EP 用完整身份与 Seen 检查提交；CP 展开局部在线统计、缩放合并和 EMPTY 分支。四卡轨迹补足唯一派发、返回、残差、AllGather 行映射和下一层消费者；PP 说明最终采样及下一 token 回送。逻辑取消与物理访问结算保持区分。",
      "evidence": [
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "只有 Seen=S 才提交该 token 输出"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "当前块的最后读取和发送都结束后才能复用其缓冲。"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "阶段 1 必须等待自己的接收/广播完成，最终采样由唯一所有者确认并把下一 token 送回需要它的阶段。"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "计算、逻辑读取、通信发送、准备、同步与驻留均有具体账目和条件。独立复算 ring 每 rank 发送公式、PP 完成时间及气泡、专家 6df 主项、CP 环流字节和计算主项均一致。四卡增长容量为 18.5703125/16.28515625 GiB；24 个远端 item 的往返为 384 KiB，输出恢复再增加 384 KiB。未把接收重复计入发送，也未把逻辑字节或容量推导当作 HBM 事务及实际时延。",
      "evidence": [
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "一次每 rank 发送 2(p−1)A/p。接收是另一计量边界，不能在“发送量”中再加一次。"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "准备包含计数、前缀和、重排与描述符，计数分桶可接近 O(N_items+E)，比较排序则可达 O(N_items log N_items)。"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "因此 B 的 MoE dispatch/return 为 384 KiB，输出恢复又为 384 KiB，边界合计 768 KiB，尚有 metadata、准备和内存重排。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "对非整除维度、低负载 decode、流水微批、专家热点、长上下文及表示变化分别说明保留的约束和调整依据。DP 与扩大 TP、PP 与 CP、热点副本与小 GEMM 的取舍均接到容量或关键路径；旧轮放置快照及副本释放条件清楚，未用平均负载或卡数直接外推收益。",
      "evidence": [
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "非整除维度可使用记录完整区间的不均匀分片、显式 padding 或更换并行度。"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "模型能在更小执行组内容纳、请求数足够时，DP 应与继续增加单请求 TP 比较；低负载时，额外副本可能只增加驻留与准备成本。"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "布局切换先准备新权重与目录，旧轮保持原放置快照；旧访问结束后才释放旧副本。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "观察、竞争解释、可控改变和反证后的修正相连。正确性诊断区分覆盖、位置、缩放、身份和布局；性能诊断区分计算、启动、慢 rank、入口拥塞与共享带宽。原 CP 失败被准确定位为非法分片，修复通过独立完整参考与真实负对照验证，没有扩大容差掩盖错误。",
      "evidence": [
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "覆盖错误先修计划；覆盖完整仍错再定位分数、mask、缩放与布局，不扩大容差掩盖"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "队列缩短而层不降说明还需检查入口拥塞或小 GEMM，不能只追求均衡"
        },
        {
          "path": "knowledge/algorithms/parallelism.md",
          "quote": "重叠是否有效以关键路径缩短为准；两条时间线相交不证明共享 HBM 或链路可以同时全速工作。"
        }
      ]
    }
  },
  "findings": [],
  "limitations": [
    "检查属于确定性 CPU 代数、消息和覆盖模型，不证明实际 NCCL 算法选择、CUDA 可见性、跨 stream 并发、故障排空、设备数值或性能。",
    "CP 参考验证有限分数及所设位置掩码；NaN、无穷、实际投影内核和后端空行语义仍需具体契约与设备验证。",
    "EP 使用固定路由和简化专家函数；去重流量按实际记录数量计算，没有执行真实 hidden 打包、router、SwiGLU 或 grouped GEMM。",
    "四卡容量和通信结果仅适用于声明的模型与布局假设；完整峰值、加载瞬态、真实拓扑、质量及 40 ms ITL 均未实测。",
    "原文核对限所供提取文本；未视觉核对 PDF 图表。CUDA 摘录不能证明完整多 GPU 专节或目标路径，正文已明确依赖来源说明并保留边界。",
    "未执行文件系统链接存在性、登记或冻结读取检查；对链接仅核对所供文本中的相对路径和对应材料身份。未验证知识改善 Agent 构建能力的使用效果。"
  ],
